from pathlib import Path
import sys
from se_harness import installer
root,prior,receipt=map(Path,sys.argv[1:4]);seed=sys.argv[4]
options=dict(external_resources=True,prior_wheel=prior,retire_files=[seed])
changes,old=installer.plan_install(root,project_name=None,mode='upgrade',**options)
before={p.relative_to(root).as_posix():p.read_bytes() for p in root.rglob('*') if p.is_file()}
original=installer._atomic_write;hit=False
def interrupted(path,content):
 global hit
 if path.name==installer.LOCK_NAME and not hit:
  hit=True;raise OSError('Injected test interruption after retirement')
 return original(path,content)
installer._atomic_write=interrupted
try:
 installer.apply_changes(root,changes,old,allow_updates=True,instruction_delivery_evidence=receipt,**options)
except OSError as exc:assert hit and str(exc)=='Injected test interruption after retirement'
else:raise AssertionError('Expected write interruption was not reached')
finally:installer._atomic_write=original
assert before=={p.relative_to(root).as_posix():p.read_bytes() for p in root.rglob('*') if p.is_file()}
print('Installed transaction restored every original byte after injected write failure')

